}

aws_subnet.db_c.code:
resource "aws_subnet" "db_c" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.21.0/24"
  availability_zone = local.azs[1]
  tags              = { Name = "${local.name}-db-c", Tier = "db" }
}

aws_nat_gateway.main.code:
resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public_a.id
  tags          = { Name = "${local.name}-nat" }
}

aws_route_table.public.code:
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = { Name = "${local.name}-public-rt" }
}

aws_route_table.app.code:
resource "aws_route_table" "app" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }
  tags = { Name = "${local.name}-app-rt" }
}

aws_s3_bucket_server_side_encryption_con.code:
resource "aws_s3_bucket_server_side_encryption_configuration" "uploads" {
  bucket = aws_s3_bucket.uploads.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "thumbnails" {
  bucket = aws_s3_bucket.thumbnails.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

aws_s3_bucket_lifecycle_configuration.th.code:
resource "aws_s3_bucket_lifecycle_configuration" "thumbnails" {
  bucket = aws_s3_bucket.thumbnails.id
  rule {
    id     = "expire-old-versions"
    status = "Enabled"
    filter {}
    noncurrent_version_expiration {
      noncurrent_days = 30
    }
  }
}

aws_sqs_queue.uploaded.code:
resource "aws_sqs_queue" "uploaded" {
  name                       = "${local.name}-uploaded"
  visibility_timeout_seconds = 360
  message_retention_seconds  = 345600
  receive_wait_time_seconds  = 20
  sqs_managed_sse_enabled    = true
  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.uploaded_dlq.arn
    maxReceiveCount     = 5
  })
}

aws_s3_bucket_notification.uploads.code:
resource "aws_s3_bucket_notification" "uploads" {
  bucket = aws_s3_bucket.uploads.id
  queue {
    queue_arn     = aws_sqs_queue.uploaded.arn
    events        = ["s3:ObjectCreated:*"]
    filter_prefix = "originals/"
  }
}

aws_dynamodb_table.photos.code:
resource "aws_dynamodb_table" "photos" {
  name         = "${local.name}-photos"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "photo_id"
  attribute {
    name = "photo_id"
    type = "S"
  }
  point_in_time_recovery {
    enabled = true
  }
  server_side_encryption {
    enabled = true
  }
  deletion_protection_enabled = true
}

aws_lambda_function.thumbnail.code:
resource "aws_lambda_function" "thumbnail" {
  function_name = "${local.name}-thumbnail"
  role          = aws_iam_role.thumbnail.arn
  runtime       = "python3.12"
  handler       = "app.handler"
  filename      = "thumbnail.zip"
  architectures = ["arm64"]
  memory_size   = 1024
  timeout       = 60
  tracing_config {
    mode = "Active"
  }
  environment {
    variables = {
      SOURCE_BUCKET = aws_s3_bucket.uploads.bucket
      DEST_BUCKET   = aws_s3_bucket.thumbnails.bucket
      PHOTOS_TABLE  = aws_dynamodb_table.photos.name
    }
  }
}

aws_lambda_event_source_mapping.uploaded.code:
resource "aws_lambda_event_source_mapping" "uploaded" {
  event_source_arn                   = aws_sqs_queue.uploaded.arn
  function_name                      = aws_lambda_function.thumbnail.arn
  batch_size                         = 10
  maximum_batching_window_in_seconds = 5
  function_response_types            = ["ReportBatchItemFailures"]
  scaling_config {
    maximum_concurrency = 20
  }
}
